param([string]$RepositoryRoot = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path)
$ErrorActionPreference='Stop';$snapshotRoot=Join-Path $RepositoryRoot 'tests/e2e/frontend-quality-platform/snapshots';$outputPath=Join-Path $RepositoryRoot 'docs/evidence/frontend/quality-platform-visual-baseline.json'
$snapshots=@(Get-ChildItem -LiteralPath $snapshotRoot -Filter 'HZ-*.png'|Sort-Object Name);if($snapshots.Count -ne 9){throw "Expected exactly 9 Hengzhun snapshots, found $($snapshots.Count)."}
$pageIds=@('quality.dashboard','quality.cases','quality.case.detail','quality.baselines','quality.runs','quality.schedules','quality.incidents','quality.knowledge','quality.releases');$cases=for($i=0;$i -lt $snapshots.Count;$i++){$snapshot=$snapshots[$i];$id=[IO.Path]::GetFileNameWithoutExtension($snapshot.Name);[ordered]@{visualId=$id;pageId=$pageIds[$i];testId="quality-platform-visual.spec.ts::$id";baselinePath=$snapshot.FullName.Substring($RepositoryRoot.Length+1).Replace('\','/');sha256=(Get-FileHash -LiteralPath $snapshot.FullName -Algorithm SHA256).Hash.ToLowerInvariant();bytes=$snapshot.Length}}
if(@($cases.sha256|Sort-Object -Unique).Count -ne 9){throw 'Hengzhun snapshots must have 9 unique hashes.'}
$evidence=[ordered]@{schemaVersion=1;evidenceType='frontend-visual-regression-baseline';generatedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceCommit=(git -C $RepositoryRoot rev-parse HEAD).Trim();contractVersion='quality-platform-api-1.0';baselineVersion='hengzhun-windows-chromium-v1';environment=[ordered]@{operatingSystem='Windows';browser='Chromium';viewport='1440x900';locale='zh-CN';timezone='Asia/Shanghai';colorScheme='light';reducedMotion=$true};businessAssertions=@('Hengzhun uses an independent nine-page information architecture spanning B0 through B7 and does not reuse bank PV identifiers.','No supplied preview image covers Hengzhun; multimodal review therefore compares the implementation with the accepted Hengzhun design document and shared design system, not with bank screenshots.','Production pages consume only the formal /api/quality/v1 contract and expose explicit loading, empty, error, and retry states.','Browser fixtures are deterministic synthetic responses used only for UI and interaction verification; they do not claim that the platform backend is implemented.','All browser automation, evidence, validation, and recovery controls are represented as local execution boundaries, while GPT receives only minimal redacted context.');cases=$cases}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $outputPath)|Out-Null;$utf8NoBom=New-Object Text.UTF8Encoding($false);[IO.File]::WriteAllText($outputPath,($evidence|ConvertTo-Json -Depth 8),$utf8NoBom);Write-Output $outputPath
